import { test, expect } from '@playwright/test';

test.describe('Async Error Handling', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should display retry option on async error', async ({ page }) => {
    await page.click(getByRole('button', { name: 'Trigger Async Action' }));

    const errorMessage = await page.getByText('An error occurred. Please try again.');
    await expect(errorMessage).toBeVisible();

    const retryButton = await page.getByRole('button', { name: 'Retry' });
    await expect(retryButton).toBeVisible();
  });

  test('should retry async action when retry option is clicked', async ({ page }) => {
    await page.click(getByRole('button', { name: 'Trigger Async Action' }));

    const retryButton = await page.getByRole('button', { name: 'Retry' });
    await expect(retryButton).toBeVisible();

    await retryButton.click();

    const successMessage = await page.getByText('Action completed successfully.');
    await expect(successMessage).toBeVisible();
  });
});
